import { useEffect, useMemo, useState } from "react";

interface User {
  id: number;
  name: string;
  email: string;
  role: UserRole;
  isActive: boolean;
}

enum UserRole {
  Admin = "ADMIN",
  Editor = "EDITOR",
  Viewer = "VIEWER",
}

type ApiResponse<T> = {
  success: boolean;
  data: T;
  message?: string;
};

const users: User[] = [
  {
    id: 1,
    name: "Alice",
    email: "alice@example.com",
    role: UserRole.Admin,
    isActive: true,
  },
  {
    id: 2,
    name: "Bob",
    email: "bob@example.com",
    role: UserRole.Editor,
    isActive: false,
  },
];

async function fetchUsers(): Promise<ApiResponse<User[]>> {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve({
        success: true,
        data: users,
        message: "Users fetched successfully",
      });
    }, 1000);
  });
}

function getUserById<T extends { id: number }>(
  items: T[],
  id: number
): T | undefined {
  return items.find((item) => item.id === id);
}

const UserCard = ({ user }: { user: User }) => {
  return (
    <div className="rounded-lg border p-4 shadow-sm">
      <h2 className="text-xl font-bold">{user.name}</h2>

      <p className="text-gray-500">{user.email}</p>

      <span
        className={`inline-block rounded px-2 py-1 text-sm ${
          user.isActive ? "bg-green-100" : "bg-red-100"
        }`}
      >
        {user.isActive ? "Active" : "Inactive"}
      </span>

      <p className="mt-2">
        Role: <strong>{user.role}</strong>
      </p>
    </div>
  );
};

export default function UserDashboard(): JSX.Element {
  const [data, setData] = useState<User[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [search, setSearch] = useState<string>("");

  useEffect(() => {
    const loadUsers = async (): Promise<void> => {
      try {
        const response = await fetchUsers();

        if (response.success) {
          setData(response.data);
        }
      } catch (error: unknown) {
        if (error instanceof Error) {
          console.error("Failed to fetch users:", error.message);
        }
      } finally {
        setLoading(false);
      }
    };

    loadUsers();
  }, []);

  const filteredUsers = useMemo(() => {
    return data.filter((user) =>
      user.name.toLowerCase().includes(search.toLowerCase())
    );
  }, [data, search]);

  const selectedUser = getUserById(filteredUsers, 1);

  if (loading) {
    return <p>Loading users...</p>;
  }

  return (
    <main className="mx-auto max-w-2xl p-6">
      <h1 className="mb-4 text-3xl font-bold">
        User Dashboard
      </h1>

      <input
        type="text"
        value={search}
        placeholder="Search users..."
        onChange={(event) => setSearch(event.target.value)}
        className="mb-6 w-full rounded border p-2"
      />

      {selectedUser && (
        <div className="mb-4">
          <p>
            Selected user: <strong>{selectedUser.name}</strong>
          </p>
        </div>
      )}

      <div className="grid gap-4">
        {filteredUsers.length > 0 ? (
          filteredUsers.map((user) => (
            <UserCard key={user.id} user={user} />
          ))
        ) : (
          <p>No users found.</p>
        )}
      </div>
    </main>
  );
}
